"use client";

import type React from "react";
import {
  Fragment,
  memo,
  useCallback,
  useEffect,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import {
  ChartBrushHandleOverlay,
  renderChartBrushHandle,
} from "./chart-brush-handle";
import {
  ChartBrushSelectionOverlay,
  type ChartBrushSelectionPattern,
} from "./chart-brush-selection-overlay";
import {
  type BrushDirection,
  type BrushDomainBounds,
  type BrushInitialPosition,
  type BrushingType,
  type BrushMoveMode,
  type BrushPoint,
  type BrushState,
  beginBrushDrag,
  beginBrushSelect,
  brushExtentToDomain,
  brushHandleRects,
  brushSelectionRect,
  createBrushState,
  dragBrush,
  endBrush,
  idleBrushState,
} from "./chart-brush-state";
import {
  ChartBrushTrackOverlay,
  type ChartBrushTrackOverlayStyle,
} from "./chart-brush-track-overlay";
import { chartCssVars, useChartStable } from "./chart-context";
import { localPoint } from "./local-point";

type Bounds = BrushDomainBounds;

interface BrushMargin {
  top: number;
  left: number;
  right: number;
  bottom: number;
}

const ZERO_MARGIN: BrushMargin = { top: 0, left: 0, right: 0, bottom: 0 };

const DEFAULT_SELECTED_BOX_STYLE: React.SVGProps<SVGRectElement> = {
  fill: "transparent",
  fillOpacity: 0,
  stroke: chartCssVars.brushBorder,
  strokeWidth: 1,
};

/** `@visx/brush` debounces window move events by 1 ms; kept for parity. */
const WINDOW_MOVE_DEBOUNCE_MS = 1;

interface BrushInteractionProps {
  xScale: unknown;
  width: number;
  height: number;
  brushDirection: BrushDirection;
  handleSize: number;
  initialBrushPosition?: BrushInitialPosition;
  /** Offset subtracted from the SVG pointer position when a selection starts. */
  startMargin: BrushMargin;
  moveMode: BrushMoveMode;
  selectedBoxStyle: React.SVGProps<SVGRectElement>;
  onChange: (bounds: Bounds | null) => void;
  onBrushEnd: (bounds: Bounds | null) => void;
}

interface ActiveBrushDrag {
  pointerId: number;
  target: Element;
  pageX: number;
  pageY: number;
  /** SVG-space pointer position at pointer down. */
  local: BrushPoint;
}

function scaleInverter(scale: unknown): (value: number) => unknown {
  const invert = (scale as { invert?: (value: number) => unknown } | null)
    ?.invert;
  // Without `invert` visx reports `{ x0: 0, x1: 0 }` (NaN -> `|| 0`).
  return typeof invert === "function"
    ? (value) => invert.call(scale, value)
    : () => Number.NaN;
}

function toDomain(state: BrushState, scale: unknown): Bounds | null {
  return brushExtentToDomain(state.extent, scaleInverter(scale));
}

/**
 * Hand-written replacement for `@visx/brush` `Brush`: one transparent hit rect
 * for the track (draw a new selection, or move the current one), the visible
 * selection rect, and the two edge handles. Pointer capture replaces visx's
 * window listeners; `chart-brush-state.ts` holds the parity rules.
 */
const ChartBrushInteraction = memo(function ChartBrushInteraction({
  xScale,
  width,
  height,
  brushDirection,
  handleSize,
  initialBrushPosition,
  startMargin,
  moveMode,
  selectedBoxStyle,
  onChange,
  onBrushEnd,
}: BrushInteractionProps) {
  const stage = useMemo(
    () => ({ width, height, direction: brushDirection }),
    [width, height, brushDirection]
  );
  const [state, setState] = useState(() =>
    createBrushState(stage, initialBrushPosition)
  );
  const stateRef = useRef(state);
  const dragRef = useRef<ActiveBrushDrag | null>(null);
  const moveTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const pendingMoveRef = useRef<{ pageX: number; pageY: number } | null>(null);

  // Latest props for the debounced window-move timer.
  const latestRef = useRef({ stage, xScale, onChange });
  useLayoutEffect(() => {
    latestRef.current = { stage, xScale, onChange };
  });

  useEffect(
    () => () => {
      if (moveTimerRef.current) {
        clearTimeout(moveTimerRef.current);
      }
    },
    []
  );

  const commitState = useCallback((next: BrushState) => {
    stateRef.current = next;
    setState(next);
  }, []);

  const startDrag = useCallback(
    (
      event: React.PointerEvent<Element>,
      next: BrushState,
      local: BrushPoint
    ) => {
      const target = event.target as Element;
      try {
        target.setPointerCapture(event.pointerId);
      } catch {
        // Pointer already gone (synthetic event); moves still bubble here.
      }
      dragRef.current = {
        pointerId: event.pointerId,
        target,
        pageX: event.pageX,
        pageY: event.pageY,
        local,
      };
      commitState(next);
      onChange(toDomain(next, xScale));
    },
    [commitState, onChange, xScale]
  );

  // Which drag starts is decided by DOM hit-testing, as in visx: the overlay
  // draws a new selection, the selection rect moves it, a handle resizes.
  const handleOverlayPointerDown = useCallback(
    (event: React.PointerEvent<SVGRectElement>) => {
      if (dragRef.current) {
        return;
      }
      const point = localPoint(event) ?? { x: 0, y: 0 };
      const next = beginBrushSelect(stateRef.current, {
        x: point.x - startMargin.left,
        y: point.y - startMargin.top,
      });
      startDrag(event, next, point);
    },
    [startDrag, startMargin.left, startMargin.top]
  );

  const handleDragPointerDown = useCallback(
    (
      type: Exclude<BrushingType, "select">,
      event: React.PointerEvent<Element>
    ) => {
      if (dragRef.current) {
        return;
      }
      const point = localPoint(event) ?? { x: 0, y: 0 };
      startDrag(event, beginBrushDrag(stateRef.current, type), point);
    },
    [startDrag]
  );

  const applyOffset = useCallback(
    (offset: BrushPoint) => {
      const latest = latestRef.current;
      const current = stateRef.current;
      if (!current.isBrushing) {
        return;
      }
      const next = dragBrush(current, offset, latest.stage, moveMode);
      commitState(next);
      latest.onChange(toDomain(next, latest.xScale));
    },
    [commitState, moveMode]
  );

  const handlePointerMove = useCallback(
    (event: React.PointerEvent<Element>) => {
      const drag = dragRef.current;
      if (!drag || event.pointerId !== drag.pointerId) {
        return;
      }
      if (moveMode === "local") {
        const point = localPoint(event) ?? { x: 0, y: 0 };
        applyOffset({ x: point.x - drag.local.x, y: point.y - drag.local.y });
        return;
      }
      pendingMoveRef.current = { pageX: event.pageX, pageY: event.pageY };
      if (moveTimerRef.current) {
        clearTimeout(moveTimerRef.current);
      }
      moveTimerRef.current = setTimeout(() => {
        moveTimerRef.current = null;
        const pending = pendingMoveRef.current;
        const active = dragRef.current;
        if (!(pending && active)) {
          return;
        }
        applyOffset({
          x: pending.pageX - active.pageX,
          y: pending.pageY - active.pageY,
        });
      }, WINDOW_MOVE_DEBOUNCE_MS);
    },
    [applyOffset, moveMode]
  );

  const handlePointerEnd = useCallback(
    (event: React.PointerEvent<Element>) => {
      const drag = dragRef.current;
      if (!drag || event.pointerId !== drag.pointerId) {
        return;
      }
      // Like visx, a window move still waiting on its debounce is dropped.
      if (moveTimerRef.current) {
        clearTimeout(moveTimerRef.current);
        moveTimerRef.current = null;
      }
      const result = endBrush(stateRef.current, moveMode);
      if (result) {
        commitState(result.state);
      }
      dragRef.current = null;
      try {
        if (drag.target.hasPointerCapture(drag.pointerId)) {
          drag.target.releasePointerCapture(drag.pointerId);
        }
      } catch {
        // Element already detached.
      }
      if (!result) {
        return;
      }
      onBrushEnd(toDomain(result.state, xScale));
      for (let i = 0; i < result.changeCount; i++) {
        onChange(toDomain(result.state, xScale));
      }
    },
    [commitState, moveMode, onBrushEnd, onChange, xScale]
  );

  // visx resets on a double-click of the overlay (not the selection).
  const handleOverlayDoubleClick = useCallback(() => {
    const next = idleBrushState();
    commitState(next);
    onChange(toDomain(next, xScale));
  }, [commitState, onChange, xScale]);

  const selection = brushSelectionRect(state.extent);
  const isBrushActive = state.extent.x0 !== -1 && state.extent.x1 !== -1;
  const { brushingType } = state;
  const selectionLocked = state.isBrushing || state.activeHandle !== null;
  const fill = "transparent";

  // Same tree as visx 4.0.0 BaseBrush (Group > overlay Drag, BrushSelection,
  // right / left BrushHandle), including the transparent "dragging" rects
  // each @visx/drag <Drag> adds while its drag is in progress. Moves and
  // pointer-up reach the group through pointer capture on the pressed target.
  return (
    <g
      className="visx-group visx-brush"
      onLostPointerCapture={handlePointerEnd}
      onPointerCancel={handlePointerEnd}
      onPointerMove={handlePointerMove}
      onPointerUp={handlePointerEnd}
      transform="translate(0, 0)"
    >
      {/* Attribute objects keep visx's attribute order in the DOM. */}
      {brushingType === "select" ? <rect {...{ width, height, fill }} /> : null}
      <rect
        {...{
          className: "visx-bar visx-brush-overlay",
          fill,
          x: 0,
          y: 0,
          width,
          height,
          onDoubleClick: handleOverlayDoubleClick,
          onPointerDown: handleOverlayPointerDown,
          style: { cursor: "crosshair" },
        }}
      />
      {brushingType === "move" ? (
        <rect {...{ width: selection.width, height: selection.height, fill }} />
      ) : null}
      <g>
        {brushingType === "move" ? (
          <rect {...{ width, height, fill, style: { cursor: "move" } }} />
        ) : null}
        <rect
          {...{
            ...selection,
            className: "visx-brush-selection",
            onPointerDown: (event: React.PointerEvent<SVGRectElement>) =>
              handleDragPointerDown("move", event),
            style: {
              pointerEvents: selectionLocked ? "none" : "all",
              cursor: "move",
            },
            ...selectedBoxStyle,
          }}
        />
      </g>
      {brushHandleRects(state.extent, handleSize, height).map((handle) => (
        <Fragment key={`handle-${handle.type}`}>
          {brushingType === handle.type ? (
            <rect {...{ width, height, fill }} />
          ) : null}
          <g>
            {brushingType === handle.type ? (
              <rect
                {...{ fill, width, height, style: { cursor: "ew-resize" } }}
              />
            ) : null}
            <g
              onPointerDown={(event) =>
                handleDragPointerDown(handle.type, event)
              }
            >
              {renderChartBrushHandle({
                x: handle.x,
                y: handle.y,
                width: handle.width,
                height: handle.height,
                className: `visx-brush-handle-${handle.type}`,
                isBrushActive,
              })}
            </g>
          </g>
        </Fragment>
      ))}
    </g>
  );
});

export interface ChartBrushSelection {
  start: Date;
  end: Date;
}

export interface ChartBrushProps {
  /** Callback when brush selection ends. Domain is the selected time range. */
  onSelectionChange?: (domain: ChartBrushSelection | null) => void;
  /** Brush direction. Default: "horizontal" for time range selection. */
  brushDirection?: "horizontal" | "vertical" | "both";
  /** Fill style for the selected region. Default: chart segment style. */
  selectedBoxStyle?: React.SVGProps<SVGRectElement>;
  /** Initial selection so the brush overlay is visible on load (e.g. first 50% of range). */
  initialSelection?: ChartBrushSelection | null;
  /** Current selection (e.g. from parent state). When set, a visible selection rect is drawn. */
  selection?: ChartBrushSelection | null;
  /** Use window move events for brush (can fix coordinate offset when SVG is in transformed container). Default: true for brush-in-strip. */
  useWindowMoveEvents?: boolean;
  /** Backdrop blur on dimmed track (0–5 px). Default: 1.5 */
  blurPx?: number;
  /** Fade dimmed regions at the outer track edges. Default: true */
  fadeOuterEdges?: boolean;
  /** Optional pattern overlay inside the brush selection window. */
  selectionPattern?: ChartBrushSelectionPattern;
}

interface ChartBrushInnerProps extends ChartBrushTrackOverlayStyle {
  brushDirection?: ChartBrushProps["brushDirection"];
  selectedBoxStyle?: ChartBrushProps["selectedBoxStyle"];
  initialSelection?: ChartBrushProps["initialSelection"];
  useWindowMoveEvents?: ChartBrushProps["useWindowMoveEvents"];
  xScale: ReturnType<typeof useChartStable>["xScale"];
  innerWidth: number;
  innerHeight: number;
  margin: ReturnType<typeof useChartStable>["margin"];
  onBrushPreview?: (bounds: Bounds | null) => void;
  onBrushCommit: (bounds: Bounds | null) => void;
  selectionPattern?: ChartBrushSelectionPattern;
}

function toDate(value: number | Date | unknown): Date {
  if (value instanceof Date) {
    return value;
  }
  if (typeof value === "number") {
    return new Date(value);
  }
  return new Date(Number(value));
}

function boundsToPixelExtent(
  bounds: Bounds | null,
  xScale: ReturnType<typeof useChartStable>["xScale"],
  innerWidth: number
): { x0: number; x1: number } | null {
  if (
    !bounds ||
    typeof bounds.x0 === "undefined" ||
    typeof bounds.x1 === "undefined"
  ) {
    return null;
  }

  const start = toDate(bounds.x0);
  const end = toDate(bounds.x1);
  const xScaleFn = xScale as (d: Date) => number;
  const x0 = Math.max(0, xScaleFn(start < end ? start : end) ?? 0);
  const x1 = Math.min(
    innerWidth,
    xScaleFn(end > start ? end : start) ?? innerWidth
  );

  if (x1 <= x0) {
    return null;
  }

  return { x0, x1 };
}

const ChartBrushInner = memo(function ChartBrushInner({
  brushDirection = "horizontal",
  selectedBoxStyle,
  initialSelection,
  useWindowMoveEvents = true,
  xScale,
  innerWidth,
  innerHeight,
  margin,
  onBrushPreview,
  onBrushCommit,
  blurPx,
  fadeOuterEdges,
  selectionPattern,
}: ChartBrushInnerProps) {
  const initialBrushPosition = useMemo(() => {
    if (!initialSelection || innerWidth <= 0 || innerHeight <= 0) {
      return undefined;
    }
    const xScaleFn = xScale as (d: Date) => number;
    const x0 = Math.max(0, xScaleFn(initialSelection.start) ?? 0);
    const x1 = Math.min(
      innerWidth,
      xScaleFn(initialSelection.end) ?? innerWidth
    );
    if (x1 <= x0) {
      return undefined;
    }
    return {
      start: { x: x0, y: 0 },
      end: { x: x1, y: innerHeight },
    };
  }, [initialSelection, xScale, innerWidth, innerHeight]);

  const [pixelExtent, setPixelExtent] = useState(() => ({
    x0: initialBrushPosition?.start.x ?? 0,
    x1: initialBrushPosition?.end.x ?? innerWidth,
  }));

  // Reset the extent when the initial selection / width change — adjusted
  // during render ("store previous props in state"), not setState in an effect.
  const [extentSource, setExtentSource] = useState({
    initialBrushPosition,
    innerWidth,
  });
  if (
    extentSource.initialBrushPosition !== initialBrushPosition ||
    extentSource.innerWidth !== innerWidth
  ) {
    setExtentSource({ initialBrushPosition, innerWidth });
    setPixelExtent({
      x0: initialBrushPosition?.start.x ?? 0,
      x1: initialBrushPosition?.end.x ?? innerWidth,
    });
  }

  const updatePixelExtent = useCallback(
    (bounds: Bounds | null) => {
      const pixels = boundsToPixelExtent(bounds, xScale, innerWidth);
      if (pixels) {
        setPixelExtent(pixels);
      }
    },
    [innerWidth, xScale]
  );

  const handleBrushPreview = useCallback(
    (bounds: Bounds | null) => {
      updatePixelExtent(bounds);
      onBrushPreview?.(bounds);
    },
    [onBrushPreview, updatePixelExtent]
  );

  const handleBrushCommit = useCallback(
    (bounds: Bounds | null) => {
      updatePixelExtent(bounds);
      onBrushCommit(bounds);
    },
    [onBrushCommit, updatePixelExtent]
  );

  return (
    <g className="chart-brush">
      <ChartBrushTrackOverlay
        blurPx={blurPx}
        fadeOuterEdges={fadeOuterEdges}
        innerHeight={innerHeight}
        innerWidth={innerWidth}
        selectionX0={pixelExtent.x0}
        selectionX1={pixelExtent.x1}
      />
      <ChartBrushSelectionOverlay
        innerHeight={innerHeight}
        innerWidth={innerWidth}
        pattern={selectionPattern}
        selectionX0={pixelExtent.x0}
        selectionX1={pixelExtent.x1}
      />
      <ChartBrushHandleOverlay
        innerHeight={innerHeight}
        innerWidth={innerWidth}
        selectionX0={pixelExtent.x0}
        selectionX1={pixelExtent.x1}
      />
      <ChartBrushInteraction
        brushDirection={brushDirection}
        handleSize={8}
        height={innerHeight}
        initialBrushPosition={initialBrushPosition}
        key={`brush-${innerWidth}-${innerHeight}`}
        moveMode={useWindowMoveEvents ? "window" : "local"}
        onBrushEnd={handleBrushCommit}
        onChange={handleBrushPreview}
        selectedBoxStyle={selectedBoxStyle ?? DEFAULT_SELECTED_BOX_STYLE}
        startMargin={useWindowMoveEvents ? margin : ZERO_MARGIN}
        width={innerWidth}
        xScale={xScale}
      />
    </g>
  );
});

export function ChartBrush({
  onSelectionChange,
  brushDirection = "horizontal",
  selectedBoxStyle,
  initialSelection,
  selection: _selection,
  useWindowMoveEvents = true,
  blurPx,
  fadeOuterEdges,
  selectionPattern,
}: ChartBrushProps) {
  const { xScale, innerWidth, innerHeight, margin, isLoaded } =
    useChartStable();

  const boundsToSelection = useCallback(
    (bounds: Bounds | null): ChartBrushSelection | null => {
      if (
        !bounds ||
        typeof bounds.x0 === "undefined" ||
        typeof bounds.x1 === "undefined"
      ) {
        return null;
      }
      const start = toDate(bounds.x0);
      const end = toDate(bounds.x1);
      if (start.getTime() === end.getTime()) {
        return null;
      }
      return {
        start: start < end ? start : end,
        end: end > start ? end : start,
      };
    },
    []
  );

  const notifySelectionChange = useCallback(
    (bounds: Bounds | null) => {
      if (!onSelectionChange) {
        return;
      }
      onSelectionChange(boundsToSelection(bounds));
    },
    [onSelectionChange, boundsToSelection]
  );

  const handleBrushPreview = useCallback(
    (bounds: Bounds | null) => {
      notifySelectionChange(bounds);
    },
    [notifySelectionChange]
  );

  const handleBrushCommit = useCallback(
    (bounds: Bounds | null) => {
      notifySelectionChange(bounds);
    },
    [notifySelectionChange]
  );

  if (!isLoaded || innerWidth <= 0 || innerHeight <= 0) {
    return null;
  }

  return (
    <ChartBrushInner
      blurPx={blurPx}
      brushDirection={brushDirection}
      fadeOuterEdges={fadeOuterEdges}
      initialSelection={initialSelection}
      innerHeight={innerHeight}
      innerWidth={innerWidth}
      margin={margin}
      onBrushCommit={handleBrushCommit}
      onBrushPreview={handleBrushPreview}
      selectedBoxStyle={selectedBoxStyle}
      selectionPattern={selectionPattern}
      useWindowMoveEvents={useWindowMoveEvents}
      xScale={xScale}
    />
  );
}

ChartBrush.displayName = "ChartBrush";

export default ChartBrush;

"use client";

import { createPortal } from "react-dom";
import type { ChartBrushOverlayHost } from "./chart-brush-track-overlay";
import { useChartPortalContainer, useChartStable } from "./chart-context";

/** Matches shadcn `ResizableHandle` withHandle pill (`h-6 w-1 rounded-lg`). */
const HANDLE_HEIGHT_PX = 24;
const HANDLE_WIDTH_PX = 4;

/** Props passed to a brush handle renderer (same shape as visx `BrushHandleRenderProps`). */
export interface BrushHandleRenderProps {
  x: number;
  y: number;
  width: number;
  height: number;
  /** `visx-brush-handle-left` / `visx-brush-handle-right`. */
  className: string;
  /** False while the brush is empty (extent -1). */
  isBrushActive: boolean;
}

/**
 * Invisible hit target for a brush resize handle.
 * Visible pills render in `ChartBrushHandleOverlay` above the blur layer.
 */
function brushHandleCursor(className: string) {
  return className.includes("left") || className.includes("right")
    ? "ew-resize"
    : "ns-resize";
}

export function renderChartBrushHandle({
  x,
  y,
  width,
  height,
  className,
}: BrushHandleRenderProps) {
  return (
    <rect
      className={className}
      fill="transparent"
      height={height}
      style={{ cursor: brushHandleCursor(className) }}
      width={width}
      x={x}
      y={y}
    />
  );
}

export interface ChartBrushHandleOverlayProps {
  innerWidth: number;
  innerHeight: number;
  /** Pixel x of the selection start within the plot area. */
  selectionX0: number;
  /** Pixel x of the selection end within the plot area. */
  selectionX1: number;
}

/** Renders brush resize pills above the outside blur portal (`z-[2]`). */
export function ChartBrushHandleOverlayContent({
  containerRef,
  margin,
  innerWidth,
  innerHeight,
  selectionX0,
  selectionX1,
}: ChartBrushHandleOverlayProps & ChartBrushOverlayHost) {
  const container = useChartPortalContainer(containerRef);
  if (!container) {
    return null;
  }

  const x0 = Math.max(0, Math.min(selectionX0, selectionX1, innerWidth));
  const x1 = Math.max(
    x0,
    Math.min(Math.max(selectionX0, selectionX1), innerWidth)
  );
  const edges = x0 === x1 ? [x0] : [x0, x1];

  const plotLeft = margin.left;
  const plotTop = margin.top;
  const handleTop = plotTop + (innerHeight - HANDLE_HEIGHT_PX) / 2;

  return createPortal(
    <div
      aria-hidden="true"
      className="pointer-events-none absolute inset-0 z-[2]"
    >
      {edges.map((edgeX) => (
        <div
          className="absolute shrink-0 rounded-lg"
          key={edgeX}
          style={{
            top: handleTop,
            left: plotLeft + edgeX - HANDLE_WIDTH_PX / 2,
            width: HANDLE_WIDTH_PX,
            height: HANDLE_HEIGHT_PX,
            backgroundColor: "var(--chart-brush-border)",
          }}
        />
      ))}
    </div>,
    container
  );
}

export function ChartBrushHandleOverlay(props: ChartBrushHandleOverlayProps) {
  const { containerRef, margin } = useChartStable();

  return (
    <ChartBrushHandleOverlayContent
      {...props}
      containerRef={containerRef}
      margin={margin}
    />
  );
}

"use client";

import {
  memo,
  type ReactNode,
  useCallback,
  useEffect,
  useMemo,
  useState,
} from "react";
import { cn } from "@/lib/utils";
import type { ChartBrushSelection } from "./chart-brush";
import { resolveBrushTrackXExtent } from "./filter-data-by-x-domain";

export interface ChartBrushLayoutState {
  xDomain: [Date, Date] | undefined;
  xDomainSlotCount: number | undefined;
  brushSelection: ChartBrushSelection | null;
  onBrushSelectionChange: (selection: ChartBrushSelection | null) => void;
}

export interface ChartBrushLayoutProps {
  /** Full dataset backing the brush strip and main chart. */
  data: Record<string, unknown>[];
  xDataKey?: string;
  /** Extends the brush track max beyond the last data row (e.g. projection horizon). */
  xExtentMax?: Date;
  /** When false, children render without brush zoom state. */
  enabled: boolean;
  /** Fixed height of the brush strip in pixels. */
  height: number;
  /** When true, the main chart area hugs content instead of growing to fill space. */
  fitMainContent?: boolean;
  className?: string;
  children: (layout: ChartBrushLayoutState) => ReactNode;
  /** Mini chart + brush handles rendered below the main chart when `enabled`. */
  brushStrip?: (layout: ChartBrushLayoutState) => ReactNode;
}

function createXAccessor(xDataKey: string) {
  return (d: Record<string, unknown>): Date => {
    const value = d[xDataKey];
    return value instanceof Date ? value : new Date(value as string | number);
  };
}

export const ChartBrushLayout = memo(function ChartBrushLayout({
  data,
  xDataKey = "date",
  xExtentMax,
  enabled,
  height,
  fitMainContent = false,
  className,
  children,
  brushStrip,
}: ChartBrushLayoutProps) {
  const xAccessor = useMemo(() => createXAccessor(xDataKey), [xDataKey]);
  const fullExtent = useMemo(
    () => resolveBrushTrackXExtent(data, xAccessor, xExtentMax),
    [data, xAccessor, xExtentMax]
  );
  const [brushSelection, setBrushSelection] =
    useState<ChartBrushSelection | null>(null);

  useEffect(() => {
    if (!fullExtent) {
      setBrushSelection(null);
      return;
    }
    setBrushSelection({ start: fullExtent[0], end: fullExtent[1] });
  }, [fullExtent]);

  const handleBrushSelectionChange = useCallback(
    (selection: ChartBrushSelection | null) => {
      if (!selection) {
        if (fullExtent) {
          setBrushSelection({ start: fullExtent[0], end: fullExtent[1] });
        }
        return;
      }
      setBrushSelection(selection);
    },
    [fullExtent]
  );

  const layoutState = useMemo<ChartBrushLayoutState>(
    () => ({
      xDomain:
        enabled && brushSelection
          ? ([brushSelection.start, brushSelection.end] as [Date, Date])
          : undefined,
      xDomainSlotCount: enabled ? data.length : undefined,
      brushSelection,
      onBrushSelectionChange: handleBrushSelectionChange,
    }),
    [brushSelection, data.length, enabled, handleBrushSelectionChange]
  );

  return (
    <div
      className={cn(
        "flex size-full min-h-0 min-w-0 flex-col",
        fitMainContent ? "justify-start gap-1" : "gap-3",
        className
      )}
    >
      <div
        className={cn(
          "min-h-0 min-w-0",
          fitMainContent ? "shrink-0" : "flex-1"
        )}
      >
        {children(layoutState)}
      </div>
      {enabled && brushStrip ? (
        <div className="min-h-0 shrink-0" style={{ height }}>
          {brushStrip(layoutState)}
        </div>
      ) : null}
    </div>
  );
});

"use client";

import { useId } from "react";
import { createPortal } from "react-dom";
import type { ChartBrushOverlayHost } from "./chart-brush-track-overlay";
import { useChartPortalContainer, useChartStable } from "./chart-context";
import {
  type PatternPresetId,
  type PatternPresetOptions,
  renderPatternPreset,
} from "./pattern-preset";

export type ChartBrushPatternPreset = PatternPresetId;

export interface ChartBrushSelectionPattern extends PatternPresetOptions {
  preset: ChartBrushPatternPreset;
  color: string;
  opacity?: number;
}

export interface ChartBrushSelectionOverlayProps {
  innerWidth: number;
  innerHeight: number;
  selectionX0: number;
  selectionX1: number;
  pattern?: ChartBrushSelectionPattern;
}

/** Pattern fill between brush handles (`z-[1]`, above blur panes). */
export function ChartBrushSelectionOverlayContent({
  containerRef,
  margin,
  innerWidth,
  innerHeight,
  selectionX0,
  selectionX1,
  pattern,
}: ChartBrushSelectionOverlayProps & ChartBrushOverlayHost) {
  const patternId = useId().replace(/:/g, "");

  const container = useChartPortalContainer(containerRef);
  if (!(container && pattern && pattern.preset !== "none")) {
    return null;
  }

  const x0 = Math.max(0, Math.min(selectionX0, selectionX1, innerWidth));
  const x1 = Math.max(
    x0,
    Math.min(Math.max(selectionX0, selectionX1), innerWidth)
  );
  const selectionWidth = x1 - x0;
  if (selectionWidth <= 0) {
    return null;
  }

  const plotLeft = margin.left;
  const plotTop = margin.top;
  const patternNode = renderPatternPreset(pattern.preset, patternId, {
    color: pattern.color,
    scale: pattern.scale,
    strokeWidth: pattern.strokeWidth,
    radius: pattern.radius,
    complement: pattern.complement,
    fill: pattern.fill,
    tileBackground: pattern.tileBackground,
  });
  if (!patternNode) {
    return null;
  }

  return createPortal(
    <svg
      aria-hidden="true"
      className="pointer-events-none absolute inset-0 z-[1]"
      height="100%"
      width="100%"
    >
      <defs>{patternNode}</defs>
      <rect
        fill={`url(#${patternId})`}
        fillOpacity={pattern.opacity ?? 1}
        height={innerHeight}
        width={selectionWidth}
        x={plotLeft + x0}
        y={plotTop}
      />
    </svg>,
    container
  );
}

export function ChartBrushSelectionOverlay(
  props: ChartBrushSelectionOverlayProps
) {
  const { containerRef, margin } = useChartStable();

  return (
    <ChartBrushSelectionOverlayContent
      {...props}
      containerRef={containerRef}
      margin={margin}
    />
  );
}

/**
 * Pure state machine behind `ChartBrush`, reproducing `@visx/brush` 4.0.0
 * (`Brush` + `BaseBrush` + `BrushSelection` + `BrushHandle` + `@visx/drag`)
 * step for step, so the emitted selections stay identical:
 *
 * - Pixel state is `start` / `end` (committed corners) plus `extent` (what is
 *   drawn). An empty brush has `extent` -1 on every side.
 * - Pointer down on the track starts a new selection at the pointer
 *   (`extent` -1, so the brush emits `null`); down on the selection moves it;
 *   down on a handle resizes from that edge. Each start emits `onChange`.
 * - Moves are offsets from the pointer-down position. With window move events
 *   (the bklit default) the offset is in page pixels and every mode is clamped
 *   to the track; without, it is in SVG units and only `move` / the right
 *   handle are clamped (visx behaviour).
 * - Pointer up commits: `onBrushEnd` then `onChange` (local mode emits one
 *   more `onChange` for `move` / handle drags). A click without a drag on the
 *   track commits `null`.
 * - Pixels convert to the domain through `scale.invert`, widened by visx's
 *   `SAFE_PIXEL` (2 px) on each side; a zero-width extent inverts to
 *   start === end, which `ChartBrush` reports as `null`.
 */

export type BrushDirection = "horizontal" | "vertical" | "both";

/** What a pointer drag does: draw a new selection, move it, or resize it. */
export type BrushingType = "select" | "move" | "left" | "right";

export type BrushHandleType = "left" | "right";

export interface BrushPoint {
  x: number;
  y: number;
}

export interface BrushExtent {
  x0: number;
  x1: number;
  y0: number;
  y1: number;
}

export interface BrushStage {
  width: number;
  height: number;
  direction: BrushDirection;
}

export interface BrushState {
  start: BrushPoint;
  end: BrushPoint;
  extent: BrushExtent;
  isBrushing: boolean;
  brushingType: BrushingType | undefined;
  /** Only set by local-mode handle drags (visx `activeHandle`). */
  activeHandle: BrushHandleType | null;
}

/**
 * `true` = window move events (page-pixel offsets, everything clamped to the
 * track); `false` = local pointer events on the brush (SVG-unit offsets).
 */
export type BrushMoveMode = "window" | "local";

/** visx `SAFE_PIXEL`: the selection is widened by this many px before inverting. */
export const BRUSH_SAFE_PIXEL = 2;

const EMPTY_EXTENT: BrushExtent = { x0: -1, x1: -1, y0: -1, y1: -1 };

function clamp(value: number, min: number, max: number): number {
  return Math.min(Math.max(value, min), max);
}

/** visx `BaseBrush.getExtent`: normalise two corners for the brush direction. */
export function getBrushExtent(
  start: Partial<BrushPoint>,
  end: Partial<BrushPoint>,
  stage: BrushStage
): BrushExtent {
  const { direction, width, height } = stage;
  return {
    x0: direction === "vertical" ? 0 : Math.min(start.x || 0, end.x || 0),
    x1: direction === "vertical" ? width : Math.max(start.x || 0, end.x || 0),
    y0: direction === "horizontal" ? 0 : Math.min(start.y || 0, end.y || 0),
    y1:
      direction === "horizontal" ? height : Math.max(start.y || 0, end.y || 0),
  };
}

export interface BrushInitialPosition {
  start?: { x?: number; y?: number };
  end?: { x?: number; y?: number };
}

/** visx `BaseBrush` constructor state (`initialBrushPosition` in pixels). */
export function createBrushState(
  stage: BrushStage,
  initial?: BrushInitialPosition | null
): BrushState {
  const extent = initial
    ? getBrushExtent(initial.start ?? {}, initial.end ?? {}, stage)
    : { ...EMPTY_EXTENT };
  return {
    start: { x: Math.max(0, extent.x0), y: Math.max(0, extent.y0) },
    end: { x: Math.max(0, extent.x1), y: Math.max(0, extent.y1) },
    extent,
    isBrushing: false,
    brushingType: undefined,
    activeHandle: null,
  };
}

/** visx `BaseBrush.getIdleState` (double-click on the track). */
export function idleBrushState(): BrushState {
  return {
    start: { x: 0, y: 0 },
    end: { x: 0, y: 0 },
    extent: { ...EMPTY_EXTENT },
    isBrushing: false,
    brushingType: undefined,
    activeHandle: null,
  };
}

/** Pointer down on the track: start a new selection at `point` (plot px). */
export function beginBrushSelect(
  state: BrushState,
  point: BrushPoint
): BrushState {
  return {
    ...state,
    start: point,
    end: { ...point },
    extent: { ...EMPTY_EXTENT },
    isBrushing: true,
    brushingType: "select",
  };
}

/** Pointer down on the selection (`move`) or a handle. */
export function beginBrushDrag(
  state: BrushState,
  type: Exclude<BrushingType, "select">
): BrushState {
  return { ...state, brushingType: type, isBrushing: true };
}

function moveSelection(
  state: BrushState,
  offset: BrushPoint,
  stage: BrushStage
): BrushState {
  const { start, end } = state;
  const validDx =
    offset.x > 0
      ? Math.min(offset.x, stage.width - end.x)
      : Math.max(offset.x, 0 - start.x);
  const validDy =
    offset.y > 0
      ? Math.min(offset.y, stage.height - end.y)
      : Math.max(offset.y, 0 - start.y);
  return {
    ...state,
    isBrushing: true,
    extent: {
      ...state.extent,
      x0: start.x + validDx,
      x1: end.x + validDx,
      y0: start.y + validDy,
      y1: end.y + validDy,
    },
  };
}

/**
 * Pointer moved by `offset` since pointer down. Returns `state` unchanged when
 * no drag is in progress.
 */
export function dragBrush(
  state: BrushState,
  offset: BrushPoint,
  stage: BrushStage,
  mode: BrushMoveMode
): BrushState {
  const { brushingType } = state;
  if (!(state.isBrushing && brushingType)) {
    return state;
  }
  if (brushingType === "move") {
    return moveSelection(state, offset, stage);
  }
  if (brushingType === "select") {
    const end =
      mode === "window"
        ? {
            x: clamp(state.start.x + offset.x, 0, stage.width),
            y: clamp(state.start.y + offset.y, 0, stage.height),
          }
        : { x: state.start.x + offset.x, y: state.start.y + offset.y };
    return { ...state, end, extent: getBrushExtent(state.start, end, stage) };
  }

  // Resize from the left / right handle.
  if (mode === "window") {
    const { x: x0, y: y0 } = state.start;
    const { x: x1, y: y1 } = state.end;
    return {
      ...state,
      isBrushing: true,
      extent: {
        ...state.extent,
        ...getBrushExtent(
          {
            x:
              brushingType === "left"
                ? clamp(x0 + offset.x, 0, stage.width)
                : x0,
            y: y0,
          },
          {
            x:
              brushingType === "right"
                ? clamp(x1 + offset.x, 0, stage.width)
                : x1,
            y: y1,
          },
          stage
        ),
      },
    };
  }
  const { start, end } = state;
  if (brushingType === "right") {
    const move = Math.max(start.x, end.x) + offset.x;
    return {
      ...state,
      activeHandle: "right",
      extent: {
        ...state.extent,
        x0: Math.max(Math.min(move, start.x), 0),
        x1: Math.min(Math.max(move, start.x), stage.width),
      },
    };
  }
  const move = Math.min(start.x, end.x) + offset.x;
  return {
    ...state,
    activeHandle: "left",
    extent: {
      ...state.extent,
      x0: Math.min(move, end.x),
      x1: Math.max(move, end.x),
    },
  };
}

export interface BrushEndResult {
  state: BrushState;
  /** How many `onChange` calls follow the single `onBrushEnd`. */
  changeCount: 1 | 2;
}

/** Pointer up: commit the drawn extent. `null` when no drag was in progress. */
export function endBrush(
  state: BrushState,
  mode: BrushMoveMode
): BrushEndResult | null {
  const { brushingType, extent } = state;
  if (!brushingType) {
    return null;
  }
  const idle = {
    isBrushing: false,
    brushingType: undefined,
    activeHandle: null,
  } as const;

  if (mode === "window" || brushingType === "move") {
    return {
      state: {
        ...state,
        ...idle,
        start: {
          x: Math.min(extent.x0, extent.x1),
          y: mode === "window" ? extent.y0 : Math.min(extent.y0, extent.y1),
        },
        end: {
          x: Math.max(extent.x0, extent.x1),
          y: Math.max(extent.y0, extent.y1),
        },
      },
      changeCount: mode === "window" ? 1 : 2,
    };
  }
  if (brushingType === "select") {
    return {
      state: {
        ...state,
        ...idle,
        start: { x: extent.x0, y: extent.y0 },
        end: { x: extent.x1, y: extent.y1 },
      },
      changeCount: 1,
    };
  }
  const start = { x: Math.min(extent.x0, extent.x1), y: extent.y0 };
  const end = {
    x: Math.max(extent.x0, extent.x1),
    y: Math.max(extent.y0, extent.y1),
  };
  return {
    state: {
      ...state,
      ...idle,
      start,
      end,
      extent: {
        x0: Math.min(start.x, end.x),
        x1: Math.max(start.x, end.x),
        y0: Math.min(start.y, end.y),
        y1: Math.max(start.y, end.y),
      },
    },
    changeCount: 2,
  };
}

/** visx selection rect geometry (`getBrushWidth` / `getBrushHeight`). */
export function brushSelectionRect(extent: BrushExtent) {
  return {
    x: Math.min(extent.x0, extent.x1),
    y: Math.min(extent.y0, extent.y1),
    width: Math.max(
      Math.max(extent.x0, extent.x1) - Math.min(extent.x0, extent.x1),
      0
    ),
    height: Math.max(
      Math.max(extent.y0, extent.y1) - Math.min(extent.y0, extent.y1),
      0
    ),
  };
}

/**
 * Handle hit rects, in visx DOM order (`right` then `left`, so `left` wins
 * where they overlap). Height is the full stage, as visx passes
 * `height: stageHeight` to `renderBrushHandle`.
 */
export function brushHandleRects(
  extent: BrushExtent,
  handleSize: number,
  stageHeight: number
): {
  type: BrushHandleType;
  x: number;
  y: number;
  width: number;
  height: number;
}[] {
  const offset = handleSize / 2;
  return [
    {
      type: "right",
      x: extent.x1 - offset,
      y: extent.y0 - offset,
      width: handleSize,
      height: stageHeight,
    },
    {
      type: "left",
      x: extent.x0 - offset,
      y: extent.y0 - offset,
      width: handleSize,
      height: stageHeight,
    },
  ];
}

export interface BrushDomainBounds {
  x0: number;
  x1: number;
}

type InvertibleScale = (value: number) => unknown;

function invertToNumber(invert: InvertibleScale, value: number): number {
  return Number((invert(value) as { valueOf(): number }).valueOf());
}

/**
 * visx `Brush.convertRangeToDomain` for the x axis: `null` for an empty brush,
 * otherwise the extent widened by `SAFE_PIXEL` and inverted (numbers, e.g.
 * epoch ms for a time scale; NaN falls back to 0 like visx's `|| 0`).
 */
export function brushExtentToDomain(
  extent: BrushExtent,
  invert: InvertibleScale
): BrushDomainBounds | null {
  const { x0, x1 } = extent;
  if (typeof x0 === "undefined" || x0 < 0) {
    return null;
  }
  const start = x0 || 0;
  const end = x1 || 0;
  const invertedStart = invertToNumber(
    invert,
    start + (start < end ? -BRUSH_SAFE_PIXEL : BRUSH_SAFE_PIXEL)
  );
  const invertedEnd = invertToNumber(
    invert,
    end + (end < start ? -BRUSH_SAFE_PIXEL : BRUSH_SAFE_PIXEL)
  );
  return {
    x0: Math.min(invertedStart, invertedEnd) || 0,
    x1: Math.max(invertedStart, invertedEnd) || 0,
  };
}

"use client";

import type { CSSProperties, RefObject } from "react";
import { createPortal } from "react-dom";
import type { Margin } from "./chart-context";
import { useChartPortalContainer, useChartStable } from "./chart-context";

/** Fade dimming panes at the outer track ends — matches series edge fade (15%). */
const BRUSH_TRACK_OUTER_FADE = 0.15;

export interface ChartBrushTrackOverlayStyle {
  /** Backdrop blur in px (0–5). Default: 1.5 */
  blurPx?: number;
  /** Fade blur at the outer left/right track ends. Default: true */
  fadeOuterEdges?: boolean;
}

function outsidePaneStyle(
  edge: "left" | "right",
  style: Required<ChartBrushTrackOverlayStyle>
): CSSProperties {
  const fadeStop = `${BRUSH_TRACK_OUTER_FADE * 100}%`;
  let mask: string | undefined;
  if (style.fadeOuterEdges) {
    mask =
      edge === "left"
        ? `linear-gradient(to right, transparent 0%, black ${fadeStop}, black 100%)`
        : `linear-gradient(to left, transparent 0%, black ${fadeStop}, black 100%)`;
  }

  return {
    pointerEvents: "none",
    backdropFilter: style.blurPx > 0 ? `blur(${style.blurPx}px)` : undefined,
    WebkitBackdropFilter:
      style.blurPx > 0 ? `blur(${style.blurPx}px)` : undefined,
    maskImage: mask,
    WebkitMaskImage: mask,
  };
}

export interface ChartBrushTrackOverlayProps
  extends ChartBrushTrackOverlayStyle {
  innerWidth: number;
  innerHeight: number;
  /** Pixel x of the selection start within the plot area. */
  selectionX0: number;
  /** Pixel x of the selection end within the plot area. */
  selectionX1: number;
}

export interface ChartBrushOverlayHost {
  containerRef: RefObject<HTMLDivElement | null>;
  margin: Margin;
}

export function ChartBrushTrackOverlayContent({
  containerRef,
  margin,
  innerWidth,
  innerHeight,
  selectionX0,
  selectionX1,
  blurPx = 1.5,
  fadeOuterEdges = true,
}: ChartBrushTrackOverlayProps & ChartBrushOverlayHost) {
  const overlayStyle: Required<ChartBrushTrackOverlayStyle> = {
    blurPx: Math.min(5, Math.max(0, blurPx)),
    fadeOuterEdges,
  };

  const container = useChartPortalContainer(containerRef);
  if (!container) {
    return null;
  }

  const x0 = Math.max(0, Math.min(selectionX0, selectionX1, innerWidth));
  const x1 = Math.max(
    x0,
    Math.min(Math.max(selectionX0, selectionX1), innerWidth)
  );
  const leftWidth = Math.max(0, x0);
  const rightWidth = Math.max(0, innerWidth - x1);

  if (leftWidth <= 0 && rightWidth <= 0) {
    return null;
  }

  const plotLeft = margin.left;
  const plotTop = margin.top;

  return createPortal(
    <div
      aria-hidden="true"
      className="pointer-events-none absolute inset-0 z-[1]"
    >
      {leftWidth > 0 ? (
        <div
          className="absolute"
          style={{
            ...outsidePaneStyle("left", overlayStyle),
            top: plotTop,
            left: plotLeft,
            width: leftWidth,
            height: innerHeight,
          }}
        />
      ) : null}
      {rightWidth > 0 ? (
        <div
          className="absolute"
          style={{
            ...outsidePaneStyle("right", overlayStyle),
            top: plotTop,
            left: plotLeft + x1,
            width: rightWidth,
            height: innerHeight,
          }}
        />
      ) : null}
    </div>,
    container
  );
}

export function ChartBrushTrackOverlay(props: ChartBrushTrackOverlayProps) {
  const { containerRef, margin } = useChartStable();

  return (
    <ChartBrushTrackOverlayContent
      {...props}
      containerRef={containerRef}
      margin={margin}
    />
  );
}
